{"path":"about.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfb;--card:#fff;--muted:#6b7280;--accent:#2b7a78;--accent-2:#ffbf69}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;background:var(--bg);color:#0f172a}
    header{background:linear-gradient(180deg,rgba(43,122,120,.06),transparent);border-bottom:1px solid rgba(15,23,42,.04)}
    .wrap{max-width:980px;margin:0 auto;padding:20px}
    nav{display:flex;align-items:center;justify-content:space-between;gap:10px}
    .brand{font-weight:700}
    .navlinks{display:flex;gap:14px;font-size:15px}
    .navlinks a{color:var(--muted);text-decoration:none}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;padding:36px 0}
    .card{background:var(--card);padding:22px;border-radius:12px;box-shadow:0 6px 20px rgba(9,10,12,.04)}
    h1{font-size:22px;margin:0 0 6px}
    p.lead{margin:0;color:var(--muted)}
    .columns{display:grid;grid-template-columns:1fr 340px;gap:18px;margin-top:18px}
    .meta{font-size:14px;color:var(--muted);padding-top:6px}
    .cta{display:inline-block;padding:10px 14px;background:var(--accent);color:white;border-radius:8px;text-decoration:none}
    .mood{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
    .mood button{padding:8px 10px;border-radius:8px;border:1px solid rgba(15,23,42,.06);background:white;cursor:pointer}
    .mood button.active{border-color:var(--accent);background:linear-gradient(90deg,rgba(43,122,120,.08),transparent)}
    .method{transition:all .35s ease;padding:14px;border-radius:10px;border:1px dashed rgba(15,23,42,.06);background:linear-gradient(180deg,rgba(255,191,105,.03),transparent)}
    footer{margin-top:22px;font-size:13px;color:var(--muted)}
    .small{font-size:13px;color:var(--muted)}
    @media(max-width:880px){.columns{grid-template-columns:1fr}}
    /* subtle decorative svg */
    .pattern{position:absolute;right:14px;top:6px;opacity:.08;width:220px;height:120px;pointer-events:none}
  </style>
</head>
<body>
  <header>
    <div class='wrap'>
      <nav>
        <div class='brand'>{{BUSINESS_NAME}}</div>
        <div class='navlinks' role='navigation' aria-label='primary'>
          <a href='index.html'>Home</a>
          <a href='about.html' aria-current='page'>The Clinician</a>
          <a href='specialties.html'>Areas</a>
          <a href='approach.html'>How I Work</a>
          <a href='book.html'>Book</a>
        </div>
      </nav>
    </div>
  </header>

  <main class='wrap'>
    <div class='hero'>
      <div class='card'>
        <h1>About the clinician</h1>
        <p class='lead'>I'm a licensed therapist offering time-limited and ongoing support for adults navigating practical life shifts, relationships, and persistent stressors. I bring clinical training with a focus on clarity and usable steps.
        </p>
        <div class='meta'>
          <div>Phone: <a href='tel:{{PHONE}}'>{{PHONE}}</a> • Email: <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a></div>
          <div class='small' style='margin-top:8px'>Sessions available in {{CITY}}, {{STATE}} and via secure telehealth. Sliding scale considered for limited openings — please inquire.</div>
        </div>
      </div>

      <aside class='card'>
        <div style='display:flex;flex-direction:column;gap:10px'>
          <div>
            <strong>Quick match</strong>
            <div class='small'>Choose how you're feeling; I'll suggest a starting approach.</div>
          </div>

          <div class='mood' role='tablist' aria-label='Mood selector' id='moodAbout'>
            <button data-key='overwhelmed' aria-pressed='false'>Overwhelmed</button>
            <button data-key='stuck' aria-pressed='false'>Stuck</button>
            <button data-key='transition' aria-pressed='false'>In Transition</button>
            <button data-key='maintenance' aria-pressed='false'>Maintaining</button>
          </div>

          <div id='methodCard' class='method' aria-live='polite'>
            <strong id='methodTitle'>A steady, practical plan</strong>
            <div id='methodBody' class='small' style='margin-top:8px'>Select how you're feeling and see a recommended first step. This is an orientation — not a diagnosis. If you are in crisis, see the note at the bottom of the page.</div>
            <a id='methodCTA' class='cta' href='{{PRIMARY_CTA_URL}}' style='display:inline-block;margin-top:12px'>{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>
      </aside>
    </div>

    <div class='columns'>
      <section class='card'>
        <h2>Clinical stance</h2>
        <p class='small'>I work collaboratively, blending structured tools with reflective inquiry. Many people find progress comes from short-term focused work (6–12 sessions) or from a longer therapeutic frame when issues are layered and recurring. Sessions are confidential within legal and ethical limits; I will explain boundaries and coordination of care when relevant.</p>

        <h3 style='margin-top:12px'>What to expect</h3>
        <ul class='small'>
          <li>A thoughtful first session to identify goals and priorities</li>
          <li>Flexible pacing: weekly, biweekly, or a short structured package</li>
          <li>Shared planning and brief skill-building between sessions when helpful</li>
        </ul>
      </section>

      <aside class='card'>
        <h3>Notes on confidentiality & scope</h3>
        <p class='small'>Conversations are confidential except where disclosure is required by law (e.g., imminent risk of harm, mandatory reporting). I will clarify limits of confidentiality and consent at intake. I do not provide emergency services; if you are in immediate danger, please call local emergency services or a crisis line.</p>
      </aside>
    </div>

    <footer class='small'>
      <div class='card' style='margin-top:18px;'>
        <strong>Clinical boundaries</strong>
        <p style='margin:8px 0' class='small'>This practice offers psychotherapy for adults. I do not provide legal, financial, or medical advice. If you have questions about medication, a primary care provider or psychiatrist can help coordinate care.</p>
      </div>
    </footer>
  </main>

  <!-- Decorative inline SVG pattern -->
  <svg class='pattern' viewBox='0 0 240 120' xmlns='http://www.w3.org/2000/svg' aria-hidden='true'>
    <defs>
      <pattern id='p' width='12' height='12' patternUnits='userSpaceOnUse'>
        <rect width='6' height='6' fill='#ffbf69'></rect>
        <rect x='6' y='6' width='6' height='6' fill='#2b7a78'></rect>
      </pattern>
    </defs>
    <rect width='240' height='120' fill='url(#p)' opacity='.12'></rect>
  </svg>

  <script>
    // Mood-to-Method (About page)
    (function(){
      const map = {
        overwhelmed: {
          title: 'Grounding & short-term structure',
          body: 'If things feel flooded, we often start with stabilization: brief pacing, activity planning, and immediate coping strategies to reduce intensity. Typical first steps include safety planning and concrete mapping of stressors.',
          cta: 'Schedule a stabilizing session'
        },
        stuck: {
          title: 'Exploratory sessions with focused goals',
          body: 'When change feels stalled, we try short cycles of work with clear targets: identifying patterns, experimenting with new behaviors, and tracking what shifts. This helps create measurable momentum.',
          cta: 'Book an exploratory visit'
        },
        transition: {
          title: 'Support through change',
          body: 'Transitions can be disorienting. We focus on decision clarity, values-aligned planning, and reducing friction so you can move through choices with steadier footing.',
          cta: 'Start transition work'
        },
        maintenance: {
          title: 'Check-ins and skill reinforcement',
          body: 'If you’re maintaining gains but want ongoing support, brief check-ins and skills refreshers can help sustain progress and prevent relapse.',
          cta: 'Arrange a check-in'
        }
      };

      const container = document.getElementById('moodAbout');
      const buttons = container.querySelectorAll('button');
      const titleEl = document.getElementById('methodTitle');
      const bodyEl = document.getElementById('methodBody');
      const ctaEl = document.getElementById('methodCTA');

      function setActive(key, btn){
        buttons.forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});
        btn.classList.add('active');btn.setAttribute('aria-pressed','true');
        const item = map[key];
        titleEl.textContent = item.title;
        bodyEl.textContent = item.body;
        ctaEl.textContent = item.cta;
        // gentle visual morph
        const card = document.getElementById('methodCard');
        card.animate([{transform:'translateY(0) scale(1)'},{transform:'translateY(-6px) scale(.998)'}],{duration:220,fill:'forwards'});
        setTimeout(()=>card.animate([{transform:'translateY(-6px) scale(.998)'},{transform:'translateY(0) scale(1)'}],{duration:300,fill:'forwards'}),230);
      }

      buttons.forEach(btn=>btn.addEventListener('click',()=>setActive(btn.dataset.key,btn)));
      // default
      buttons[0] && buttons[0].click();
    })();
  </script>

  <script>
    // Basic accessibility: keyboard support for mood buttons
    document.querySelectorAll('[role=tablist] button').forEach(btn=>{
      btn.addEventListener('keydown',e=>{
        if(e.key==='ArrowRight' || e.key==='ArrowDown') btn.nextElementSibling && btn.nextElementSibling.focus();
        if(e.key==='ArrowLeft' || e.key==='ArrowUp') btn.previousElementSibling && btn.previousElementSibling.focus();
      });
    });
  </script>

  <footer style='max-width:980px;margin:18px auto 40px;font-size:13px;color:var(--muted)'>
    <div>Confidentiality, scope, and crisis guidance: Records are kept securely and discussed with you; certain circumstances (harm to self/others, abuse of a minor) require disclosure. If you are in immediate danger, call emergency services or your local crisis line.</div>
  </footer>
</body>
</html>"} 
